<script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script>
<script>
document.querySelectorAll('.js-finalize-date-drafts').forEach(function (form) {
    form.addEventListener('submit', function (event) {
        event.preventDefault();
        const total = form.querySelectorAll('input[name="session_ids[]"]').length;
        Swal.fire({icon:'warning',title:'Finalkan '+total+' kelas?',html:'Seluruh <b>draft</b> pada tanggal ini akan menjadi final dan masuk ke analitik. Kelas belum input tidak diubah.',showCancelButton:true,confirmButtonText:'Ya, finalkan',cancelButtonText:'Batal',confirmButtonColor:'#16a34a'}).then(function (result) { if (result.isConfirmed) HTMLFormElement.prototype.submit.call(form); });
    });
});
</script>
